    const [dx, dy] = RIG[S.cfg.skin] || RIG.classic, r = G.run, lp = (a, b) => a + (b - a) * r, W = GAIT.walk, U = GAIT.run, TAU = Math.PI * 2;
    const Sx = lp(W.S, U.S), H = lp(W.H, U.H), duty = lp(W.duty, U.duty);
